#################################################################
#    Classes: Root & Core Dimensions
#################################################################

ea:Assessment a owl:Class ;
    rdfs:label "Assessment"@en ;
    skos:altLabel "Educational Assessment"@en , "Educational Evaluation"@en , "Exam"@en , "Examination"@en , "Test"@en ;
    rdfs:comment "The systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve student learning."@en .

ea:AssessmentDimension a owl:Class ;
    rdfs:label "Assessment Dimension"@en ;
    rdfs:comment "Reified value space dimensions along which educational assessments are categorized."@en .

ea:MeasurementProperty a owl:Class ;
    rdfs:label "Measurement Property"@en ;
    rdfs:comment "Psychometric and evaluative characteristics of assessments, including reliability, validity, and score models."@en .

ea:CurricularEntity a owl:Class ;
    rdfs:label "Curricular Entity"@en ;
    rdfs:comment "Entities within the curriculum and learning design, such as learning outcomes and alignments."@en .

ea:EvaluationInstrumentComponent a owl:Class ;
    rdfs:label "Evaluation Instrument Component"@en ;
    rdfs:comment "Structural components of assessments and scoring guides, including rubrics and test items."@en .

#################################################################
#    Axis 1: Assessment Purpose
#################################################################

ea:AssessmentPurpose a owl:Class ;
    rdfs:label "Assessment Purpose"@en ;
    rdfs:subClassOf ea:AssessmentDimension ;
    owl:disjointUnionOf (
        ea:PlacementPurpose
        ea:FormativePurpose
        ea:SummativePurpose
        ea:DiagnosticPurpose
        ea:InterimPurpose
        ea:ScreeningPurpose
    ) .

ea:PlacementPurpose a owl:Class ;
    rdfs:label "Placement Purpose"@en ;
    rdfs:subClassOf ea:AssessmentPurpose .

ea:FormativePurpose a owl:Class ;
    rdfs:label "Formative Purpose"@en ;
    rdfs:subClassOf ea:AssessmentPurpose .

ea:SummativePurpose a owl:Class ;
    rdfs:label "Summative Purpose"@en ;
    rdfs:subClassOf ea:AssessmentPurpose .

ea:DiagnosticPurpose a owl:Class ;
    rdfs:label "Diagnostic Purpose"@en ;
    rdfs:subClassOf ea:AssessmentPurpose .

ea:InterimPurpose a owl:Class ;
    rdfs:label "Interim Purpose"@en ;
    skos:altLabel "Benchmark Purpose"@en ;
    rdfs:subClassOf ea:AssessmentPurpose .

ea:ScreeningPurpose a owl:Class ;
    rdfs:label "Screening Purpose"@en ;
    rdfs:subClassOf ea:AssessmentPurpose .

ea:PlacementAssessment a owl:Class ;
    rdfs:label "Placement Assessment"@en ;
    skos:altLabel "Initial Assessment"@en , "Placement Evaluation"@en , "Pre-assessment"@en , "Threshold Knowledge Test"@en ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ]
        )
    ] .

ea:FormativeAssessment a owl:Class ;
    rdfs:label "Formative Assessment"@en ;
    skos:altLabel "Assessment for Learning"@en , "Classroom Assessment"@en , "Educative Assessment"@en , "Formative Evaluation"@en , "Formative Feedback"@en ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ]
        )
    ] .

ea:SummativeAssessment a owl:Class ;
    rdfs:label "Summative Assessment"@en ;
    skos:altLabel "Assessment of Learning"@en , "Summative Evaluation"@en ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ]
        )
    ] .

ea:DiagnosticAssessment a owl:Class ;
    rdfs:label "Diagnostic Assessment"@en ;
    skos:altLabel "Diagnostic Evaluation"@en , "Diagnostic Test"@en , "Diagnostic Testing"@en ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:subClassOf ea:FormativeAssessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ]
        )
    ] ;
    rdfs:comment "Tension in corpus: In some passages, diagnostic assessment is presented as a coordinate alternative category alongside placement, formative, and summative assessments; in other passages, diagnostic assessment is explicitly classified as a common form or subset of formative assessment."@en .

ea:InterimAssessment a owl:Class ;
    rdfs:label "Interim Assessment"@en ;
    skos:altLabel "Benchmark Assessment"@en , "Benchmark Test"@en , "Interim Test"@en ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:InterimPurpose ]
        )
    ] ;
    rdfs:comment "Tension in corpus: Some educators classify interim/benchmark assessments as formative because they are used diagnostically, whereas others classify them as summative or distinct evaluative measures."@en .

ea:ScreeningAssessment a owl:Class ;
    rdfs:label "Screening Assessment"@en ;
    skos:altLabel "Screening Test"@en ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:ScreeningPurpose ]
        )
    ] .

#################################################################
#    Axis 2: Referencing Scheme
#################################################################

ea:ReferencingScheme a owl:Class ;
    rdfs:label "Referencing Scheme"@en ;
    rdfs:subClassOf ea:AssessmentDimension ;
    owl:disjointUnionOf (
        ea:CriterionReferencing
        ea:NormReferencing
        ea:IpsativeReferencing
    ) .

ea:CriterionReferencing a owl:Class ;
    rdfs:label "Criterion Referencing"@en ;
    rdfs:subClassOf ea:ReferencingScheme .

ea:NormReferencing a owl:Class ;
    rdfs:label "Norm Referencing"@en ;
    rdfs:subClassOf ea:ReferencingScheme .

ea:IpsativeReferencing a owl:Class ;
    rdfs:label "Ipsative Referencing"@en ;
    skos:altLabel "Forced-Choice Referencing"@en ;
    rdfs:subClassOf ea:ReferencingScheme .

ea:CriterionReferencedAssessment a owl:Class ;
    rdfs:label "Criterion-Referenced Assessment"@en ;
    skos:altLabel "Criterion-Referenced Test"@en , "Standards-Based Assessment"@en ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasReferencingScheme ; owl:someValuesFrom ea:CriterionReferencing ]
        )
    ] .

ea:NormReferencedAssessment a owl:Class ;
    rdfs:label "Norm-Referenced Assessment"@en ;
    skos:altLabel "Grading on the Curve"@en , "Norm-Referenced Test"@en , "Normative Assessment"@en ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasReferencingScheme ; owl:someValuesFrom ea:NormReferencing ]
        )
    ] .

ea:IpsativeAssessment a owl:Class ;
    rdfs:label "Ipsative Assessment"@en ;
    skos:altLabel "Self-Comparison Assessment"@en ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasReferencingScheme ; owl:someValuesFrom ea:IpsativeReferencing ]
        )
    ] .

#################################################################
#    Axis 3: Formality
#################################################################

ea:FormalityLevel a owl:Class ;
    rdfs:label "Formality Level"@en ;
    rdfs:subClassOf ea:AssessmentDimension ;
    owl:disjointUnionOf (
        ea:FormalFormality
        ea:InformalFormality
    ) .

ea:FormalFormality a owl:Class ;
    rdfs:label "Formal Formality"@en ;
    rdfs:subClassOf ea:FormalityLevel .

ea:InformalFormality a owl:Class ;
    rdfs:label "Informal Formality"@en ;
    rdfs:subClassOf ea:FormalityLevel .

ea:FormalAssessment a owl:Class ;
    rdfs:label "Formal Assessment"@en ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:FormalFormality ]
        )
    ] .

ea:InformalAssessment a owl:Class ;
    rdfs:label "Informal Assessment"@en ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:InformalFormality ]
        )
    ] .

#################################################################
#    Axis 4: Source / Setting
#################################################################

ea:AssessmentSource a owl:Class ;
    rdfs:label "Assessment Source"@en ;
    rdfs:subClassOf ea:AssessmentDimension ;
    owl:disjointUnionOf (
        ea:InternalSource
        ea:ExternalSource
    ) .

ea:InternalSource a owl:Class ;
    rdfs:label "Internal Source"@en ;
    rdfs:subClassOf ea:AssessmentSource .

ea:ExternalSource a owl:Class ;
    rdfs:label "External Source"@en ;
    rdfs:subClassOf ea:AssessmentSource .

ea:InternalAssessment a owl:Class ;
    rdfs:label "Internal Assessment"@en ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasAssessmentSource ; owl:someValuesFrom ea:InternalSource ]
        )
    ] .

ea:ExternalAssessment a owl:Class ;
    rdfs:label "External Assessment"@en ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasAssessmentSource ; owl:someValuesFrom ea:ExternalSource ]
        )
    ] .

#################################################################
#    Axis 5: Objectivity
#################################################################

ea:ObjectivityType a owl:Class ;
    rdfs:label "Objectivity Type"@en ;
    rdfs:subClassOf ea:AssessmentDimension ;
    owl:disjointUnionOf (
        ea:ObjectiveScoring
        ea:SubjectiveScoring
    ) .

ea:ObjectiveScoring a owl:Class ;
    rdfs:label "Objective Scoring"@en ;
    rdfs:subClassOf ea:ObjectivityType .

ea:SubjectiveScoring a owl:Class ;
    rdfs:label "Subjective Scoring"@en ;
    rdfs:subClassOf ea:ObjectivityType .

ea:ObjectiveAssessment a owl:Class ;
    rdfs:label "Objective Assessment"@en ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:ObjectiveScoring ]
        )
    ] ;
    rdfs:comment "Tension in corpus: While assessment is conventionally dichotomized into objective and subjective, critics argue that truly objective assessment does not exist because all assessments possess inherent human, cultural, and content selection biases."@en .

ea:SubjectiveAssessment a owl:Class ;
    rdfs:label "Subjective Assessment"@en ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:SubjectiveScoring ]
        )
    ] .

#################################################################
#    Axis 6: Standardization
#################################################################

ea:StandardizationStatus a owl:Class ;
    rdfs:label "Standardization Status"@en ;
    rdfs:subClassOf ea:AssessmentDimension ;
    owl:disjointUnionOf (
        ea:StandardizedStatus
        ea:NonStandardizedStatus
