ea:isAssessmentItemOf
    a owl:ObjectProperty ;
    owl:inverseOf ea:hasAssessmentItem ;
    rdfs:domain ea:AssessmentItem ;
    rdfs:range ea:Assessment ;
    rdfs:label "is assessment item of"@en .

ea:hasItemStem
    a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:AssessmentItem ;
    rdfs:range ea:ItemStem ;
    rdfs:label "has item stem"@en .

ea:hasItemOption
    a owl:ObjectProperty ;
    rdfs:domain ea:AssessmentItem ;
    rdfs:range ea:ItemOption ;
    rdfs:label "has item option"@en .

ea:hasKeyOption
    a owl:ObjectProperty ;
    rdfs:subPropertyOf ea:hasItemOption ;
    rdfs:domain ea:AssessmentItem ;
    rdfs:range ea:KeyOption ;
    rdfs:label "has key option"@en .

ea:hasDistractorOption
    a owl:ObjectProperty ;
    rdfs:subPropertyOf ea:hasItemOption ;
    rdfs:domain ea:AssessmentItem ;
    rdfs:range ea:DistractorOption ;
    rdfs:label "has distractor option"@en .

ea:ObjectiveItem
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentItem ;
    rdfs:label "Objective Item"@en ;
    rdfs:comment "An item format scored with a single pre-determined correct answer."@en .

ea:SubjectiveItem
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentItem ;
    rdfs:label "Subjective Item"@en ;
    rdfs:comment "An item format requiring constructed or free responses."@en .

[] a owl:AllDisjointClasses ;
   owl:members ( ea:ObjectiveItem ea:SubjectiveItem ) .

ea:MultipleChoiceItem
    a owl:Class ;
    rdfs:subClassOf ea:ObjectiveItem ;
    rdfs:label "Multiple Choice Item"@en ;
    skos:altLabel "MCQ"@en, "Multiple Choice Question"@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:ObjectiveItem
            [ a owl:Restriction ; owl:onProperty ea:hasKeyOption ; owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ; owl:onClass ea:KeyOption ]
            [ a owl:Restriction ; owl:onProperty ea:hasDistractorOption ; owl:minQualifiedCardinality "1"^^xsd:nonNegativeInteger ; owl:onClass ea:DistractorOption ]
        )
    ] .

ea:MultipleResponseItem
    a owl:Class ;
    rdfs:subClassOf ea:ObjectiveItem ;
    rdfs:label "Multiple Response Item"@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:ObjectiveItem
            [ a owl:Restriction ; owl:onProperty ea:hasKeyOption ; owl:minQualifiedCardinality "2"^^xsd:nonNegativeInteger ; owl:onClass ea:KeyOption ]
        )
    ] .

ea:TrueFalseItem
    a owl:Class ;
    rdfs:subClassOf ea:ObjectiveItem ;
    rdfs:label "True-False Item"@en .

ea:MatchingItem
    a owl:Class ;
    rdfs:subClassOf ea:ObjectiveItem ;
    rdfs:label "Matching Item"@en .

[] a owl:AllDisjointClasses ;
