ea:TestAdministrationRelatedError a owl:Class ; rdfs:subClassOf ea:ReliabilityErrorSource ; rdfs:label "Test Administration-Related Error"@en .
ea:TestRelatedError a owl:Class ; rdfs:subClassOf ea:ReliabilityErrorSource ; rdfs:label "Test-Related Error"@en .

